INSERT INTO equipas (slug, sigla, nome, escalao, competicao, treinador, descricao, ordem) VALUES
('seniores', 'SEN', 'Seniores', 'Seniores', 'AF Porto – Divisão de Elite', NULL, 'A equipa principal do clube, nos campeonatos distritais de futsal da AF Porto, com jogos no Pavilhão da Cohaemato.', 1),
('sub-23', 'B', 'Equipa B / Sub-23', 'Seniores B', 'AF Porto', NULL, 'A equipa de transição entre a formação e a equipa principal, onde os jovens ganham ritmo competitivo.', 2),
('sub-19', 'S19', 'Sub-19', 'Juniores A', 'AF Porto – Futsal Juniores A', NULL, 'O último passo da formação antes da equipa principal.', 3),
('sub-17', 'S17', 'Sub-17', 'Juniores B', 'AF Porto – Juniores B, Divisão de Elite', NULL, 'Atletas em plena evolução competitiva, a preparar a passagem aos juniores.', 4),
('sub-15', 'S15', 'Sub-15', 'Juniores C', 'AF Porto – Futsal Juniores C', NULL, 'Jovens atletas a consolidar a técnica e a leitura de jogo.', 5),
('sub-13', 'S13', 'Sub-13', 'Juniores D', 'AF Porto – Futsal Juniores D', NULL, 'Fase de desenvolvimento em que o jogo coletivo ganha forma. Segundo o zerozero, o clube tem 5 títulos regionais neste escalão (4 da 1.ª Divisão e 1 Taça).', 6),
('sub-11', 'S11', 'Sub-11', 'Juniores E', 'AF Porto – Futsal Juniores E', NULL, 'Onde tudo começa: aprender a jogar, a divertir-se e a pertencer ao clube.', 7);
